        array("id" => "s1e55", "season" => 1, "number" => 55, "name" => "Room 402", "airdate" => "17 May 2005", "runtime" => 25, "rating" => 8.7, "summary" => "Tenma escapes with Milch and tries to warn Eva that she is in danger. Eva is staying in room 402 of the Hotel Steigent. Tenma is unable to contact Eva, so he heads to her room.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/212/531622.jpg"),
