        array("id" => "s1e64", "season" => 1, "number" => 64, "name" => "The Baby's Depression", "airdate" => "19 Jul 2005", "runtime" => 25, "rating" => 8.7, "summary" => "The Baby is a prominent right-wing extremist in Frankfurt. He became Capek's right-hand man with the aim of creating a new world order, but lately he's been distrustful of Capek's words and actions.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/212/531631.jpg"),
