        array("id" => "s1e66", "season" => 1, "number" => 66, "name" => "Welcome Back", "airdate" => "2 Aug 2005", "runtime" => 25, "rating" => 8.7, "summary" => "Capek is at the mercy of a gun-toting Nina and leads her to Johan by car. On the way there, Capek reveals that Johan came just before Nina did, and that Johan told him to tell Nina where he was.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/212/531633.jpg"),
        array("id" => "s1e67", "season" => 1, "number" => 67, "name" => "I'm Home", "airdate" => "9 Aug 2005", "runtime" => 25, "rating" => 8.7, "summary" => "Johan, during his confrontation with Anna, reveals what he endured in the Red Rose Mansion as a child. As Tenma and Anna embark further on the monster's trail, Johan is already ahead of them, now knowing where his path of destruction will end.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/212/531634.jpg"),
