        array("id" => "s1e69", "season" => 1, "number" => 69, "name" => "A Peaceful Home", "airdate" => "23 Aug 2005", "runtime" => 25, "rating" => 8.7, "summary" => "Inspector Lunge and Grimmer are standing on a hill that overlooks the town of Ruhenheim. A disaster will soon befall this seemingly peaceful town. The townspeople will become suspicious of each other and then annihilate each other.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/212/531636.jpg"),
