        array("id" => "s1e71", "season" => 1, "number" => 71, "name" => "The Magnificent Steiner's Rage", "airdate" => "6 Sep 2005", "runtime" => 25, "rating" => 8.7, "summary" => "In the pouring rain, in the town of Ruhenheim, people have become suspicious of each other and have begun killing each other. Inspector Lunge is saving the surviving townspeople as he searches for the leader of the group that is inciting the massacre.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/212/531638.jpg"),
        array("id" => "s1e72", "season" => 1, "number" => 72, "name" => "Man Without a Name", "airdate" => "13 Sep 2005", "runtime" => 25, "rating" => 8.7, "summary" => "Inspector Lunge tracks down Roberto, the leader of the inciters, and charges in. But Inspector Lunge ends up being defeated by Roberto, who declares that he has no name. Meanwhile, upon meeting Bonaparta, Tenma goes into the town with him to end everything.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/212/531640.jpg"),
